import com.fream.back.domain.m22.entity.Xjm45;
import com.fream.back.global.entity.Xzh80Entity;
import jakarta.persistence.*;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Getter;
import lombok.NoArgsConstructor;


@Entity @jakarta.persistence.Table(name = "sale_bid")
@Getter
@NoArgsConstructor
@AllArgsConstructor
@Builder
public class Xzt63 extends Xzh80Entity {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "seller_id")
    private Xjm45 seller;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "product_size_id")
    private Xcc44 productSize;

    private int bidPrice;

    @Enumerated(EnumType.STRING)
    @Builder.Default
    private Xkh73Status status = Xkh73Status.PENDING;

    @OneToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "sale_id")
    private Xpj42 sale;

    @OneToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "order_id")
    private Xhq12 order;



    @Column(nullable = false)
    @Builder.Default
    private boolean isInstantSale = false;

    public void assignSale(Xpj42 sale) {
        this.sale = sale;
        this.status = Xkh73Status.MATCHED;
    }

    public void assignOrder(Xhq12 order) {
        this.order = order;
        this.status = Xkh73Status.MATCHED;
    }
    public void markAsInstantSale() {
        this.isInstantSale = true;
    }

    public void updateStatus(Xkh73Status newStatus) {
        this.status = newStatus;
    }
}
package com.fream.back.domain.m99.entity;

import com.fream.back.domain.m30.entity.Xcc44;
import com.fream.back.domain.m85.entity.Xpj42;
import com.fream.back.domain.m22.entity.Xjm45;
import com.fream.back.global.entity.Xzh80Entity;
import jakarta.persistence.*;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Getter;
import lombok.NoArgsConstructor;




@Entity @jakarta.persistence.Table(name = "order_bid")
@Getter
@NoArgsConstructor
@AllArgsConstructor
@Builder
public class Xtw92 extends Xzh80Entity {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "user_id")
    private Xjm45 user;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "product_size_id")
    private Xcc44 productSize;

    private int bidPrice;

    @Builder.Default
    @Enumerated(EnumType.STRING)
    private Xkh73Status status = Xkh73Status.PENDING;

    @OneToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "order_id")
    private Xhq12 order;

    @OneToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "sale_id")
    private Xpj42 sale;


    @Builder.Default
    @Column(nullable = false)
    private boolean isInstantPurchase = false;







    public void assignOrder(Xhq12 order) {

        if (this.order != null && this.order != order) {
            Xhq12 oldOrder = this.order;
            this.order = null;
            if (oldOrder.getOrderBid() == this) {
                oldOrder.assignOrderBid(null);
            }
        }


        this.order = order;


        if (order != null) {
            this.status = Xkh73Status.MATCHED;


            if (order.getOrderBid() != this) {
                order.assignOrderBid(this);
            }
        }
    }






    public void assignSale(Xpj42 sale) {
        this.sale = sale;
        this.status = Xkh73Status.MATCHED;
    }




    public void markAsInstantPurchase() {
        this.isInstantPurchase = true;
    }






    public void updateStatus(Xkh73Status newStatus) {
        this.status = newStatus;
    }
}

