package com.fream.back.domain.m99.service.command;

import com.fream.back.domain.m99.entity.Xkh73Status;
import com.fream.back.domain.m99.entity.Xhq12;
import com.fream.back.domain.m99.entity.Xtw92;
import com.fream.back.domain.m99.exception.*;
import com.fream.back.domain.m99.repository.Xtw92Repository;
import com.fream.back.domain.m64.dto.Xjt45RequestDto;
import com.fream.back.domain.m30.entity.Xcc44;
import com.fream.back.domain.m30.service.p11.Xcc44QueryService;
import com.fream.back.domain.m85.entity.Xpj42;
import com.fream.back.domain.m85.entity.Xzt63;
import com.fream.back.domain.m85.service.query.Xzt63QueryService;
import com.fream.back.domain.m22.entity.Xjm45;
import com.fream.back.domain.m22.service.query.Xjm45QueryService;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;




@Service
@RequiredArgsConstructor
@Slf4j
public class Xtw92CommandService {

    private final Xtw92Repository orderBidRepository;
    private final Xhq12CommandService orderCommandService;
    private final Xcc44QueryService productSizeQueryService;
    private final Xjm45QueryService userQueryService;
    private final Xzt63QueryService saleBidQueryService;












    @Transactional
    public Xtw92 createOrderBid(String email, Long productSizeId, int bidPrice) {
        try {

            validateCreateOrderBidInput(email, productSizeId, bidPrice);


            Xjm45 user = userQueryService.findByEmail(email);


            Xcc44 productSize = productSizeQueryService.findById(productSizeId)
                    .orElseThrow(() -> new Xpb58Exception("해당 사이즈를 찾을 수 없습니다(ID: " + productSizeId + ")"));


            Xhq12 order = orderCommandService.createOrderFromBid(user, productSize, bidPrice);


            Xtw92 orderBid = createAndSaveOrderBid(user, productSize, bidPrice, order);

            return orderBid;
        } catch (Exception e) {
            handleOrderBidCreationException(e, "주문 입찰 생성");
            return null;
        }
    }




    private void validateCreateOrderBidInput(String email, Long productSizeId, int bidPrice) {
        if (email == null || email.trim().isEmpty()) {
            throw new Xqx49Exception("사용자 이메일이 없습니다.");
        }
        if (productSizeId == null) {
            throw new Xpb58Exception("상품 사이즈 ID가 없습니다.");
        }
        if (bidPrice <= 0) {
            throw new Xrs16Exception("입찰 가격은 0보다 커야 합니다. 현재 가격: " + bidPrice);
        }
    }




    private Xtw92 createAndSaveOrderBid(Xjm45 user, Xcc44 productSize, int bidPrice, Xhq12 order) {
        Xtw92 orderBid = Xtw92.builder()
                .user(user)
                .productSize(productSize)
                .bidPrice(bidPrice)
                .status(Xkh73Status.PENDING)
                .order(order)
                .build();


        orderBid.assignOrder(order);

        return orderBidRepository.save(orderBid);
    }














    @Transactional
    public Xtw92 createInstantOrderBid(String buyerEmail, Long saleBidId, Long addressId,
                                          boolean isWarehouseStorage, Xjt45RequestDto paymentRequest) {
        try {

            validateInstantOrderBidInput(buyerEmail, saleBidId, addressId, paymentRequest);


            Xjm45 buyer = userQueryService.findByEmail(buyerEmail);


            Xzt63 saleBid = getSaleBidAndValidate(saleBidId);
            Xpj42 sale = saleBid.getSale();


            Xhq12 order = orderCommandService.createInstantOrder(
                    buyer,
                    saleBid,
                    addressId,
                    isWarehouseStorage,
                    paymentRequest
            );


            Xtw92 orderBid = createInstantOrderBid(order, saleBid, sale);

            return orderBid;
        } catch (Exception e) {
            handleOrderBidCreationException(e, "즉시 구매 주문 입찰 생성");
            return null;
        }
    }




    private void validateInstantOrderBidInput(String buyerEmail, Long saleBidId, Long addressId, Xjt45RequestDto paymentRequest) {
        if (buyerEmail == null || buyerEmail.trim().isEmpty()) {
            throw new Xqx49Exception("구매자 이메일이 없습니다.");
        }
        if (saleBidId == null) {
            throw new Xbk76Exception("판매 입찰 ID가 없습니다.");
        }
        if (addressId == null) {
            throw new Xzj75Exception("배송지 ID가 없습니다.");
        }
        if (paymentRequest == null) {
            throw new Xtv55Exception("결제 정보가 없습니다.");
        }
    }




    private Xzt63 getSaleBidAndValidate(Long saleBidId) {
        Xzt63 saleBid = saleBidQueryService.findById(saleBidId);
        if (saleBid == null) {
            throw new Xbk76Exception("판매 입찰을 찾을 수 없습니다(ID: " + saleBidId + ")");
        }

        Xpj42 sale = saleBid.getSale();
        if (sale == null) {
            throw new Xzj75Exception("판매 입찰과 연결된 판매 정보가 없습니다.");
        }

        return saleBid;
    }




    private Xtw92 createInstantOrderBid(Xhq12 order, Xzt63 saleBid, Xpj42 sale) {
        Xcc44 productSize = saleBid.getProductSize();

        Xtw92 orderBid = Xtw92.builder()
                .user(order.getUser())
                .productSize(productSize)
                .bidPrice(saleBid.getBidPrice())
                .status(Xkh73Status.MATCHED)
                .order(order)
                .sale(sale)
                .build();


        orderBid.assignOrder(order);


        orderBid.markAsInstantPurchase();
        return orderBidRepository.save(orderBid);
    }




    private void handleOrderBidCreationException(Exception e, String operation) {
        if (e instanceof Xhq12Exception) {
            throw (Xhq12Exception) e;
        }
        log.error("{} 중 오류 발생: {}", operation, e.getMessage(), e);
        throw new Xrd49Exception(operation + " 중 오류가 발생했습니다: " + e.getMessage(), e);
    }








    @Transactional
    public void matchOrderBid(Xtw92 orderBid) {
        try {
            if (orderBid == null) {
                throw new Xsb40Exception("주문 입찰 정보가 없습니다.");
            }

            if (orderBid.getStatus() == Xkh73Status.MATCHED) {
                throw new Xcw90Exception("이미 매칭된 주문 입찰입니다(ID: " + orderBid.getId() + ")");
            }

            orderBid.updateStatus(Xkh73Status.MATCHED);
        } catch (Exception e) {
            if (e instanceof Xhq12Exception) {
                throw e;
            }
            log.error("주문 입찰 매칭 중 오류 발생: {}", e.getMessage(), e);
            throw new Xfb77Exception("주문 입찰 매칭 중 오류가 발생했습니다: " + e.getMessage(), e);
        }
    }









    @Transactional
    public void deleteOrderBid(Long orderBidId) {
        try {

            Xtw92 orderBid = orderBidRepository.findById(orderBidId)
                    .orElseThrow(() -> new Xsb40Exception("해당 주문 입찰을 찾을 수 없습니다(ID: " + orderBidId + ")"));


            if (orderBid.getSale() != null) {
                throw new Xcw90Exception("주문 입찰이 판매와 연결되어 있어 삭제할 수 없습니다.");
            }


            if (orderBid.getStatus() == Xkh73Status.MATCHED) {
                throw new Xcw90Exception("이미 매칭된 주문 입찰은 삭제할 수 없습니다.");
            }


            if (orderBid.getOrder() != null) {
                orderCommandService.deleteOrder(orderBid.getOrder().getId());
            }


            orderBidRepository.delete(orderBid);
        } catch (Exception e) {
            if (e instanceof Xhq12Exception) {
                throw e;
            }
            log.error("주문 입찰 삭제 중 오류 발생: {}", e.getMessage(), e);
            throw new Xzs26Exception("주문 입찰 삭제 중 오류가 발생했습니다: " + e.getMessage(), e);
        }
    }
